function validate([n, edges, s, d, k]) {
  if (!Number.isInteger(n) || n < 2 || n > 500) return 'n is an integer from 2 to 500.';
  if (!Array.isArray(edges) || edges.length < n - 1 || edges.length > Math.min(10000, n * (n - 1) / 2)) return 'edges needs between n - 1 and min(10^4, n(n-1)/2) entries.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const seen = new Set();
  let parts = n;
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [u, v, w] with integers.';
    const [u, v, w] = edge;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge endpoints are between 0 and n - 1.';
    if (u === v) return 'The graph has no self-loops.';
    if (w < 1 || w > 1000000) return 'Edge weights are between 1 and 10^6.';
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (seen.has(key)) return 'Two edges join the same pair of nodes.';
    seen.add(key);
    const a = find(u);
    const b = find(v);
    if (a !== b) {
      parent[a] = b;
      parts--;
    }
  }
  if (parts !== 1) return 'The graph must be connected.';
  if (![s, d, k].every(x => Number.isInteger(x) && x >= 0 && x <= n - 1)) return 's, d and k are between 0 and n - 1.';
  if (s === d) return 's and d must be different nodes.';
  return null;
}

