function shortestPathWithHops(n, edges, s, d, k) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
    graph[v].push([u, w]);
  }
  // dist[node][used] is the cheapest known cost to reach node after hopping used edges.
  const dist = Array.from({ length: n }, () => new Array(k + 1).fill(Infinity));
  const heap = [];
  const push = (cost, node, used) => {
    dist[node][used] = cost;
    heap.push([cost, node, used]);
    let index = heap.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (heap[parent][0] <= heap[index][0]) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let smallest = index;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === index) return top;
      [heap[smallest], heap[index]] = [heap[index], heap[smallest]];
      index = smallest;
    }
  };
  push(0, s, 0);
  while (heap.length > 0) {
    const [cost, node, used] = pop();
    if (cost > dist[node][used]) continue;
    if (node === d) {
      return cost;
    }
    for (const [next, weight] of graph[node]) {
      if (cost + weight < dist[next][used]) {
        push(cost + weight, next, used);
      }
      if (used < k && cost < dist[next][used + 1]) {
        push(cost, next, used + 1);
      }
    }
  }
  return -1;
}

