function shortestPathWithHops(n, edges, s, d, k) {
  // Bellman-Ford over layers: best[j][v] is the cheapest cost to v with j hops; relax until nothing changes.
  const best = Array.from({ length: k + 1 }, () => new Array(n).fill(Infinity));
  best[0][s] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let j = 0; j <= k; j++) {
      for (const [u, v, w] of edges) {
        for (const [a, b] of [[u, v], [v, u]]) {
          if (best[j][a] + w < best[j][b]) { best[j][b] = best[j][a] + w; changed = true; }
          if (j < k && best[j][a] < best[j + 1][b]) { best[j + 1][b] = best[j][a]; changed = true; }
        }
      }
    }
  }
  return Math.min(...best.map(row => row[d]));
}

