function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const large = size === 'large';
  const n = large ? 300 + pick(201) : 2 + pick(5);
  const most = Math.min(large ? 2000 : 10000, n * (n - 1) / 2);
  const chain = rand() < 0.5;
  const heavy = large || rand() < 0.4;
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [order[i], order[j]] = [order[j], order[i]];
  }
  const edges = [];
  const seen = new Set();
  const add = (u, v) => {
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (u === v || seen.has(key)) return;
    seen.add(key);
    edges.push(rand() < 0.5 ? [u, v, 0] : [v, u, 0]);
  };
  // A spanning tree keeps the graph connected: a long chain, or each node tied to a random earlier one.
  for (let i = 1; i < n; i++) add(order[i], order[chain ? i - 1 : pick(i)]);
  const extra = large ? (chain ? pick(200) : most - (n - 1)) : pick(most - (n - 1) + 1);
  while (edges.length < n - 1 + extra) add(pick(n), pick(n));
  for (const edge of edges) edge[2] = heavy ? 1 + pick(1000000) : 1 + pick(10);
  for (let i = edges.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  let s = pick(n);
  let d = pick(n - 1);
  if (d >= s) d++;
  if (chain && rand() < 0.6) {
    s = order[0];
    d = order[n - 1];
  }
  const k = large ? pick(chain ? 12 : 4) : pick(n);
  return [n, edges, s, d, k];
}
